"""Actual speed-test Lua preserves registered timer identity across race lifecycle."""
import itertools,json
from pathlib import Path
from unittest.mock import patch
import pytest
from lupa.lua54 import LuaRuntime
from tools.script_recovery.convert_quest_unit import UnitConverter
from tools.script_recovery.build_readable_unit import readable_file
ROOT=Path(__file__).resolve().parents[2]
@pytest.fixture(scope='module')
def generated(tmp_path_factory):
 c=UnitConverter(ROOT/'refs/script_recovery/guild_training/translation_unit_typed.json')
 unit=json.loads((ROOT/'refs/script_recovery/guild_training/units/Q_GuildTraining.json').read_text())
 unit['entities']={'WillApprentice':unit['entities']['WillApprentice']}
 unit['quest']['functions']={};unit['quest']['helpers']={}
 out=tmp_path_factory.mktemp('will_abort_flags')
 with patch.object(c,'constructor_defaults',return_value={}):c.convert(unit,out)
 source=(out/'FSE/GuildTraining/Entities/WillApprentice.lua').read_text()
 return source,readable_file(source)[0]
def plain(v):
 if hasattr(v,'items'):return [plain(x) for x in v.values()]
 return v
HARNESS='\nreturn function(accept,already,taskTicks,shotDelay,heroDelay,limit,scoreStep,oldHigh,outside,warning)\n local frames,events,spokenUntil,questionAt=0,{},0,0\n local timerCount,resourceCount,movieCount,hudCount=0,0,0,0\n local timers,resources,movies,maps={[77]=0},{},{},{}\n local talked=false;local testStart\n local state={GlobalSkillGrade=5,GlobalMeleeGrade=5,GlobalWillGrade=2,HeroTakingGuildTest=already,HighestSkillScore=oldHigh,WillScore=0}\n local q\n local function event(...)events[#events+1]={...}end\n local hero={};local marker={IsNull=function()return false end,GetPos=function()return{x=13,y=7,z=3}end};local ring,village={},{}\n local me={}\n function me:SetFriendsWithEverythingFlag(flag)assert(flag)end\n function me:IsPerformingScriptTask()return frames<spokenUntil end\n function me:IsTalkedToByHero()if not talked and frames>=1 then talked=true;return true end;return false end\n function me:MoveToPosition(pos,speed,kind,a,b)assert(pos.x==13 and speed==3 and kind==0 and not a and b);event("move",frames)end\n function me:ClearCommands()event("clear",frames)end\n function me:Speak(target,key,a,b,c,d)\n  assert(target==hero and a==0 and not b and c and not d);event("speak",key,frames);spokenUntil=frames+taskTicks\n  while frames<spokenUntil and frames<limit do q:NewScriptFrame(me)end\n  return frames<limit\n end\n q={}\n function q:GetHero()return hero end\n function q:GetStateInt(name)assert(name=="WillHelpTimer");return 77 end\n function q:GetHeroWillEnergy()return oldHigh end\n function q:IsActiveThreadTerminating()return frames>=limit end\n function q:NewScriptFrame(actor)\n  assert(actor==me);frames=frames+1;event("frame",frames)\n  for id,value in pairs(timers)do timers[id]=math.max(value-1,0)end\n  if testStart then state.WillScore=state.WillScore+scoreStep end\n  return frames<limit\n end\n function q:IsQuestActive(name)assert(name=="Q_GuildTrainingDeparture");return true end\n function q:GetMasterGameState(name)\n  if name=="GuildWarningOccuring"then return warning and testStart~=nil and frames>=testStart+2 end\n  assert(state[name]~=nil,name);return state[name]\n end\n function q:SetMasterGameState(name,value)assert(state[name]~=nil,name);state[name]=value;event("master",name,value,frames);if name=="WillScore" and value==0 then testStart=frames end end\n function q:GetThingWithScriptName(name)if name=="WillApprenticeTargetMarker"then return marker end;assert(name=="ArcheryRing");return ring end\n function q:GetNearestWithDefName(actor,name)assert(actor==me and name=="VILLAGE_GUILD_COMPLEX_INSIDE");return village end\n function q:EntityAttachToVillage(actor,target)assert(actor==me and target==village)end\n function q:EntitySetAsKillable(actor,a,b)assert(actor==me and not a and b)end\n function q:SetIsPushableByHero(actor,value)assert(actor==me and not value)end\n function q:SetThingHasInformation(actor,a,b,c)assert(actor==me and not a and b and not c);event("info",frames)end\n function q:ClearThingHasInformation(actor)assert(actor==me);event("clearInfo",frames)end\n function q:IsDistanceBetweenThingsOver(a,b,d)\n  if a==me then assert(b==marker and d==4);return false end\n  assert(a==hero and b==me and d==30);return outside and testStart~=nil and frames>=testStart+2\n end\n function q:IsDistanceBetweenThingsUnder(a,b,d)assert(a==me and b==hero and d==10);return true end\n function q:EntitySetFacingAngleTowardsThing(a,b,flag)assert(a==me and b==hero and not flag)end\n function q:RegisterTimer()timerCount=timerCount+1;local id=100+timerCount*17;timers[id]=0;event("register",id);return id end\n function q:SetTimer(id,value)assert(timers[id]~=nil);timers[id]=value;event("setTimer",id,value,frames)end\n function q:GetTimer(id)assert(timers[id]~=nil);return timers[id]end\n function q:DeregisterTimer(id)assert(timers[id]~=nil,"duplicate or wrong timer cleanup");timers[id]=nil;event("deregister",id)end\n function q:GetHealth(actor)assert(actor==me);return 6 end\n function q:PauseAllNonScriptedEntities(flag)event("pause",flag,frames)end\n function q:GiveHeroYesNoQuestion(key,...)questionAt=frames;event("question",key,frames)end\n function q:MsgIsQuestionAnsweredYesOrNo()return frames<questionAt+1 and -1 or accept and 1 or 0 end\n function q:SetPlayerUsingWillDummies(flag)event("dummies",flag,frames)end\n function q:MsgOnHeroCastSpell()return frames>=questionAt+shotDelay end\n function q:ReadGlobalGameDataFloat(offset)assert(offset==0xf08);return 4 end\n function q:ReadGlobalGameDataFloatAt(offset,index)assert(offset==0xecc and index>=0 and index<=6);return({11,10,8,6,3,1,0})[index+1]end\n function q:AddQuestInfoCounter(icon,start,scale)assert(start==0 and scale==1);hudCount=hudCount+1;event("counter",hudCount,icon);return 200+hudCount end\n function q:AddQuestInfoTimer(id,icon,scale)assert(timers[id]~=nil and icon=="HUD_CLOCK_ICON" and scale==1);return 202 end\n function q:DisplayQuestInfo(flag)event("display",flag,frames)end\n function q:UpdateQuestInfoCounter(id,value,max)assert(max==-1 and (id==201));event("counterUpdate",id,value,frames)end\n function q:RemoveQuestInfoElement(id)assert(id>=201 and id<=203);event("removeHud",id)end\n function q:IsHeroControlledByPlayer()return testStart==nil or frames>=testStart+heroDelay end\n function q:FixMovieSequenceCamera(flag)event("camera",flag,frames)end\n local r={}\n function q:RetailResources()return r end\n function r:NewResource()resourceCount=resourceCount+1;resources[resourceCount]=true;event("resource",resourceCount);return resourceCount end\n function r:PrepareResource(id)assert(resources[id])end\n function r:TryAcquire(id,actor,kind)assert(resources[id] and kind==4 and (id==1 and actor==me or id==2 and actor==hero));return id==1 or testStart~=nil and frames>=testStart+heroDelay end\n function r:ScriptThing(id)assert(id==1 and resources[id]);return me end\n function r:ReleaseResource(id)assert(resources[id],"duplicate resource cleanup");resources[id]=nil;event("release",id)end\n function r:StartMovie(name)assert(name=="");movieCount=movieCount+1;movies[movieCount]=true;event("movie",movieCount,frames);return movieCount end\n function r:DestroyMovie(id)assert(movies[id],"duplicate movie cleanup");movies[id]=nil;event("destroy",id)end\n function r:NewActorMap()maps[301]=true;return 301 end\n function r:SetActor(id,name,resource)assert(maps[id] and resources[resource] and (name=="ME" or name=="HERO"));event("actor",name,resource)end\n function r:DestroyActorMap(id)assert(maps[id]);maps[id]=nil;event("destroyMap",id)end\n function r:RunMacro(key,id,a,b)assert(maps[id] and not a and b);event("macro",key,frames)end\n function q:AddNewConversation(actor,a,b)assert(actor==me and not a and not b);return 401 end\n function q:AddPersonToConversation(id,actor)assert(id==401 and actor==hero)end\n function q:AddLineToConversation(id,key,a,b,flag)assert(id==401 and a==me and b==hero and not flag);event("line",key,frames)end\n debug.sethook(function()error("instruction budget")end,"",50000)\n Init(q,me);Main(q,me)\n debug.sethook()\n assert(timers[77]~=nil,"persistent help timer wrongly released");timers[77]=nil;assert(next(timers)==nil and next(resources)==nil and next(movies)==nil and next(maps)==nil,"lifetime leak")\n return events\nend\n'

@pytest.mark.parametrize('style',(0,1))
@pytest.mark.parametrize('task,shot,limit,step,energy,outside,warning',list(itertools.product((0,2),(0,3),(8,15),(1,3),(0,100),(False,True),(False,True))))
def test_help_dialogue_preserves_abort_and_grade(generated,style,task,shot,limit,step,energy,outside,warning):
 lua=LuaRuntime();lua.execute(generated[style]);events=plain(lua.execute(HARNESS)(True,False,task,shot,0,limit,step,energy,outside,warning))
 macros=[e[1] for e in events if e[0]=='macro']
 start=max(2+2*task,1+shot)
 complete=not outside and not warning and start+4<limit
 assert len(macros)==(2 if complete else 0)
 if complete:
  expected='APLUS_PRIZE' if step==3 else 'D'
  assert macros==['CS_GUILD_DEPARTURE_WILL_TEST_END','CS_GUILD_DEPARTURE_WILL_TEST_'+expected]
  grade=[e[2] for e in events if e[0]=='master' and e[1]=='GlobalWillGrade']
  assert grade==[7 if step==3 else 3]
  scores=[e[2] for e in events if e[0]=='counterUpdate'];assert scores==[step,step*2,step*3,step*4]
 assert sum(e[0]=='deregister' for e in events)==sum(e[0]=='register' for e in events)
 assert sum(e[0]=='movie' for e in events)==sum(e[0]=='destroy' for e in events)
 assert sum(e[0]=='resource' for e in events)==sum(e[0]=='release' for e in events)
